// Builds the Slack text + decides if the report "needs attention".
const REJECT_ALERT_PCT = 10;   // alert if >= 10% of turns ended with no safe reply
const TRAFFIC_DROP_PCT = 50;   // alert if traffic fell >= 50% vs the previous day...
const MIN_PREV_TURNS   = 20;   // ...but only when the previous day had at least this many turns

const m = $('Yesterday Metrics').first().json;
const asList = (v) => (typeof v === 'string' ? JSON.parse(v) : (v || []));
const intents = asList($('Intent Mix').first().json.intents);
const reasons = asList($('Top Routing Reasons').first().json.reasons);

const num  = (v) => Number(v ?? 0);
const pct  = (part, whole) => (whole > 0 ? (100 * part) / whole : 0);
const delta = (cur, prev) => (prev > 0 ? Math.round((100 * (cur - prev)) / prev) : null);
const arrow = (d) => (d === null ? 'n/a' : d > 0 ? `▲ ${d}%` : d < 0 ? `▼ ${Math.abs(d)}%` : '= 0%');

const turns = num(m.turns), prevTurns = num(m.prev_turns);
const cost = num(m.total_cost), prevCost = num(m.prev_cost), warn = num(m.cost_warn_usd);
const rejectedPct = pct(num(m.all_rejected), turns);

// ---- attention rules ----
const alerts = [];
if (turns > 0 && rejectedPct >= REJECT_ALERT_PCT)
  alerts.push(`${rejectedPct.toFixed(1)}% of turns had no safe reply (limit ${REJECT_ALERT_PCT}%)`);
if (warn > 0 && cost >= warn)
  alerts.push(`AI cost $${cost.toFixed(2)} reached the daily warning level ($${warn.toFixed(2)})`);
if (prevTurns >= MIN_PREV_TURNS && turns < prevTurns * (1 - TRAFFIC_DROP_PCT / 100))
  alerts.push(`Traffic dropped ${Math.abs(delta(turns, prevTurns))}% vs the previous day - check the channels`);

// ---- message ----
const lines = [`*ShopAssist daily report - ${m.day}*`];
if (turns === 0) {
  lines.push('No conversations were processed yesterday.');
} else {
  const p = (n) => `${n} (${pct(num(n), turns).toFixed(0)}%)`;
  const p95 = m.p95_latency_ms == null ? 'n/a' : `${(num(m.p95_latency_ms) / 1000).toFixed(1)} s`;
  const score = m.avg_reviewer_score == null ? 'n/a' : num(m.avg_reviewer_score).toFixed(2);
  lines.push(`Conversations: *${turns}* (${arrow(delta(turns, prevTurns))} vs previous day)`);
  lines.push(`Auto-send: ${p(m.auto_send)} | Human review: ${p(m.human_review)} | No safe reply: ${p(m.all_rejected)}`);
  lines.push(`Human overrides: ${num(m.overridden)}`);
  lines.push(`AI cost: *$${cost.toFixed(2)}* (${arrow(delta(cost, prevCost))}) | avg $${(cost / turns).toFixed(4)} per turn`);
  lines.push(`Latency p95: ${p95} | Avg reviewer score: ${score}`);
  if (intents.length) lines.push('Intents: ' + intents.map((i) => `${i.intent} ${i.n}`).join(', '));
  if (reasons.length) lines.push('Top routing reasons: ' + reasons.map((r) => `${r.reason} ${r.n}`).join(', '));
}
if (alerts.length) lines.push('', ':warning: *Needs attention*', ...alerts.map((a) => `• ${a}`));

return [{ json: { text: lines.join('\n'), severity: alerts.length ? 'attention' : 'normal', alerts } }];
